let catalogue;const pending=new Map();
const database=()=>new Promise((resolve,reject)=>{const r=indexedDB.open('erosionsector-automatic-resources',1);r.onupgradeneeded=()=>r.result.createObjectStore('sources');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
async function read(key){try{const db=await database();return await new Promise(resolve=>{const r=db.transaction('sources').objectStore('sources').get(key);r.onsuccess=()=>{db.close();resolve(r.result);};r.onerror=()=>{db.close();resolve(null);};});}catch{return null;}}
async function save(key,pack){try{const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('sources','readwrite');tx.objectStore('sources').put(pack,key);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}catch{/* Rendering still works when browser storage is full or disabled. */}}
function load(source,progress){const key=source.id+':'+source.sha256;if(pending.has(key))return pending.get(key);const result=(async()=>{const cached=await read(key);if(cached)return cached;const pack=await new Promise((resolve,reject)=>{const worker=new Worker(new URL('./automatic-resources-worker.mjs',import.meta.url),{type:'module'});const timer=setTimeout(()=>{worker.terminate();reject(Error(source.file+' 다운로드 시간이 초과되었습니다. 다시 열어 주세요.'));},120000);const end=()=>{clearTimeout(timer);worker.terminate();};worker.onmessage=({data})=>{if(data.progress)progress?.(data.progress);if(data.error){end();reject(Error(data.error));}if(data.pack){end();resolve(data.pack);}};worker.onerror=e=>{end();reject(Error(e.message||'리소스 처리 실패'));};worker.postMessage({source});});await save(key,pack);return pack;})();pending.set(key,result);result.catch(()=>pending.delete(key));return result;}
export async function automaticResources(namespaces,progress){if(!namespaces.length)return [];catalogue??=fetch('./block-resources/sources.json').then(r=>{if(!r.ok)throw Error('공식 리소스 목록을 불러오지 못했습니다.');return r.json();}).catch(e=>{catalogue=null;throw e;});const {sources}=await catalogue,ids=new Set(),ordered=[];const select=source=>{if(ids.has(source.id))return;ids.add(source.id);for(const dep of source.dependsOn||[])select(sources.find(s=>s.id===dep));ordered.push(source);};for(const s of sources)if(s.namespaces.some(ns=>namespaces.includes(ns)))select(s);const packs=[];for(const source of ordered)packs.push(await load(source,progress));return packs;}
